SELECT club.Club_ID, club.Name, club.Manager, club.Captain, club.Manufacturer, club.Sponsor, player.Name
FROM club
JOIN player ON club.Club_ID = player.Club_ID;

SELECT Customers.customer_first_name, Customers.customer_middle_initial, Customers.customer_last_name, Customer_Payment_Methods.payment_method_code AS payment_method
FROM Customers
LEFT JOIN Customer_Payment_Methods ON Customers.customer_id = Customer_Payment_Methods.customer_id;

SELECT DISTINCT Questions.Question_Text FROM Questions
WHERE Questions.Question_Text IS NOT NULL AND Questions.Question_Text IS NOT DISTINCT NULL
ORDER BY Questions.Question_Text ASC;

