SELECT COUNT(*) AS student_count, Ref_Event_Types.event_type_code AS event_type_code, Ref_Event_Types.event_type_description AS event_type_description FROM Student_Events

GROUP BY event_type_code, event_type_description

ORDER BY student_count DESC;

SELECT S.bio_data, S.achievement_details, S.achievement_type_code
FROM Students S
JOIN Achievements A ON S.student_id = A.student_id;

SELECT Transcripts.date_of_transcript, Transcript_details.transcript_details
FROM Transcripts
JOIN Transcript_details ON Transcripts.transcript_id = Transcript_details.transcript_id;

