SELECT institution.Institution_Name, conference.Location, conference.Founded
  FROM conference
  JOIN institution ON conference.Conference_ID = institution.Institution_ID;

SELECT institution.Institution_Name, conference.Location, institution.Foundered
FROM institution
JOIN conference ON institution.Institution_ID = conference.Institution_ID;

SELECT Addresses.country, Addresses.town_city, Addresses.line_1_number_building, Addresses.line_2_number_street, Addresses.line_3_area_locality, Addresses.zip_postcode, Addresses.county_state_province
FROM Addresses
WHERE Addresses.country IS NOT NULL OR Addresses.town_city IS NOT NULL OR Addresses.line_1_number_building IS NOT NULL OR Addresses.line_2_number_street IS NOT NULL OR Addresses.line_3_area_locality IS NOT NULL OR Addresses.zip_postcode IS NOT NULL OR Addresses.county_state_province IS NOT NULL;

SELECT COUNT(*) AS total_properties
FROM Properties
WHERE garage_yn OR parking_lots = 1;

SELECT Users.first_name, Users.last_name
FROM Users
WHERE Users.is_buyer = FALSE AND Users.is_seller = FALSE AND Users.is_seller IS NULL;
